mapper.select:
SELECT b.id, b.bill_no, b.bill_period, b.bill_amount, b.paid_amount, b.status, b.pay_deadline, b.pay_time, b.create_time, b.update_time, o.owner_name, o.owner_phone, h.house_number, bd.building_name, f.item_name FROM bill_info b LEFT JOIN owner_info o ON b.owner_id = o.id AND o.is_deleted = 0 LEFT JOIN house_info h ON b.house_id = h.id AND h.is_deleted = 0 LEFT JOIN building_info bd ON h.building_id = bd.id AND bd.is_deleted = 0 LEFT JOIN fee_item f ON b.fee_item_id = f.id AND f.is_deleted = 0 WHERE b.is_deleted = 0
AND b.bill_no LIKE CONCAT('%', #{billNo}, '%')
AND b.owner_id = #{ownerId}
AND b.house_id = #{houseId}
AND b.fee_item_id = #{feeItemId}
AND b.status = #{status}
AND b.bill_period LIKE CONCAT('%', #{billPeriod}, '%')
AND b.create_time >= #{startTime}
AND b.create_time <= #{endTime}
AND bd.community_id = #{communityId}
ORDER BY b.create_time DESC
